from gurobipy import *

def solve_problem():
    m = Model("Disaster_Response_Logistics")
    m.setParam("TimeLimit", 300)  # Set time limit to 300 seconds

    # Data
    depots = list(range(6))  # D0..D5
    units = list(range(6))  # U0..U5
    supplies = list(range(3))  # S0..S2
    days = list(range(4))  # Day0..Day3

    demands = [[[30.51, 12.93, 36.29, 35.75], [45.13, 42.94, 43.77, 23.1], [16.14, 40.06, 15.65, 47.22]], [[41.89, 46.28, 41.78, 24.8], [35.41, 33.38, 35.05, 26.25], [34.18, 13.96, 28.69, 30.77]], [[18.45, 33.12, 45.16, 11.48], [38.97, 16.74, 10.23, 38.88], [16.16, 35.79, 12.5, 35.47]], [[45.23, 49.12, 21.49, 39.75], [49.27, 32.72, 46.43, 37.62], [44.66, 47.57, 31.85, 27.28]], [[24.11, 27.31, 30.42, 38.76], [34.02, 40.1, 21.19, 13.22], [23.74, 40.98, 21.1, 14.66]], [[15.09, 31.47, 24.74, 35.92], [25.52, 33.02, 19.13, 21.67], [43.29, 15.86, 16.32, 29.15]]]
    depot_supplies = [[[30.67, 37.02, 34.81, 35.49], [33.07, 32.44, 31.84, 35.42], [26.19, 41.92, 26.09, 41.14]], [[33.51, 35.12, 32.95, 27.5], [45.26, 34.3, 34.49, 27.35], [33.61, 31.4, 17.43, 31.39]], [[42.59, 34.54, 37.27, 43.22], [39.89, 48.95, 29.31, 39.78], [31.98, 47.57, 24.41, 40.21]], [[42.14, 32.87, 34.24, 33.13], [56.31, 34.42, 39.97, 24.14], [42.31, 40.68, 21.15, 41.29]], [[36.83, 41.61, 48.52, 39.45], [50.21, 41.13, 43.18, 36.48], [33.61, 27.29, 17.18, 31.81]], [[32.27, 29.53, 42.95, 46.44], [45.1, 35.03, 24.03, 22.2], [42.26, 38.06, 20.4, 42.57]]]
    transport_costs = [[2.38, 2.93, 2.78, 2.92, 2.81, 2.89], [4.96, 3.93, 3.89, 4.18, 1.78, 4.87], [1.51, 1.14, 2.54, 1.56, 4.54, 3.05], [2.94, 1.97, 1.57, 4.31, 1.05, 1.62], [2.08, 3.62, 2.95, 2.78, 2.64, 4.83], [4.17, 2.57, 3.66, 3.45, 1.69, 4.93]]
    risk_costs = [[179.61, 173.85, 131.27, 166.99, 111.43, 121.48], [109.88, 56.17, 136.22, 187.15, 186.05, 152.77], [97.98, 182.31, 53.63, 69.64, 80.24, 137.8], [192.63, 170.97, 165.16, 126.17, 170.34, 98.12], [140.51, 189.93, 100.93, 179.88, 97.62, 94.08], [87.86, 180.82, 176.28, 187.77, 169.61, 159.11]]
    supply_volumes = [0.96, 1.52, 1.73]
    penalty_costs = [71.64, 61.49, 84.78]
    vehicle_cost = 10.0
    vehicle_capacity = 100.0
    total_vehicles = 20

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
